sources.app.tsx:
// Color cycling: cozy pixel-art scenes animated the 8-bit way. Each is drawn
// once, a byte a cell, and from then on only its palette moves: ranges of
// colors rotate where the art laid them out in the direction of travel, so
// water falls, waves roll in, rain and snow come down, smoke rises, flames
// lick and stars twinkle. A frame costs the app a palette of 256 colors, and
// the panel rewrites only the cells whose color changed (frameos.pixels, the
// 8-bit palette mode). The footer along the bottom has Previous and Next, the
// scene's name, the frame rate and Hide; hidden, a tap along the bottom edge
// brings it back. A tap or a click anywhere else is the next scene, and so
// are Enter, Space, the right arrow and a swipe left; the left arrow or a
// swipe right is the previous one.
import { setSeed } from './random'
import { Art, BAR, INK, cycled } from './art'
import { countFrame, drawFooter, footerHit, footerIn, footerOut, placeFooter, restartCount } from './footer'
import { makeFalls } from './falls'
import { makeHarbor } from './harbor'
import { makeRain } from './rain'
import { makeSnow } from './snow'
import { makeAurora } from './aurora'
import { makeCampfire } from './campfire'

const SCENES: Record<string, (cols: number, rows: number) => Art> = {
  falls: makeFalls,
  harbor: makeHarbor,
  rain: makeRain,
  snow: makeSnow,
  aurora: makeAurora,
  campfire: makeCampfire,
}
const ORDER = Object.keys(SCENES)
// The footer's names, in the letters its font has.
const NAMES: Record<string, string> = {
  falls: 'WATERFALL',
  harbor: 'HARBOR',
  rain: 'RAINY NIGHT',
  snow: 'SNOWY CABIN',
  aurora: 'NORTHERN LIGHTS',
  campfire: 'CAMPFIRE',
}

// What outlives a render while the interpreter does. An ESP32 short of
// memory drops the interpreter, and the scene is drawn again.
let key = ''
let art: Art | null = null
// Scenes drawn already, by their key: drawing one is the slow part of a
// swipe on an ESP32, a few seconds, and its cells are 26 KB at 160x160.
const drawn: Record<string, Art> = {}
let size = 1
let renders = 0
let counting = false
const palette = new Uint32Array(256)

function sceneOf(config: any): string {
  return SCENES[config.scene] ? config.scene : ORDER[0]
}

function footerOn(config: any): boolean {
  return config.footer !== false && config.footer !== 'false'
}

export function get(app, context) {
  footerOut() // the art as it was drawn, under where the footer went
  const config = app.config
  const scene = sceneOf(config)
  const width = context.imageWidth || app.frame.width
  const height = context.imageHeight || app.frame.height
  // Automatic: about 240 cells across the short side, 160 on an ESP32, where
  // drawing the scene the first time is the slow part.
  const asked = Math.round(Number(config.pixelSize) || 0)
  const px = asked >= 1 ? Math.min(32, asked) : Math.max(2, Math.round(Math.min(width, height) / (app.frame.embedded ? 160 : 240)))
  const seed = Math.round(Number(config.seed) || 0)
  const next = [scene, px, width, height, seed].join(':')
  if (next !== key || !art) {
    key = next
    art = drawn[next]
    if (!art) {
      setSeed(seed > 0 ? seed : Date.now() ^ (Math.random() * 0x7fffffff))
      art = SCENES[scene](Math.max(8, Math.floor(width / px)), Math.max(8, Math.floor(height / px)))
      drawn[next] = art
    }
    size = px
    renders = 0
    restartCount() // the rate shown becomes this scene's
  }
  // The colors move with the clock, so they keep their pace at any frame rate
  // and are where the time says after a deep sleep; a fixed step a render
  // instead makes every render the same, from the first.
  const step = Number(config.msPerRender) || 0
  cycled(art, step > 0 ? renders++ * step : Date.now(), palette)
  placeFooter(art.cells, art.cols, art.rows, size, width, height, context.round === true)
  if (footerOn(config)) {
    if (!counting) restartCount(true)
    counting = true
    countFrame()
    // A panel that is not fast never animates: no frame rate to show, nor a Hide to press.
    drawFooter(NAMES[scene], BAR, INK, app.frame.fast ?? app.frame.paper !== true)
    footerIn(art.cells)
  } else {
    counting = false
  }
  return frameos.pixels(art.cells, palette, { width: art.cols, height: art.rows, pixelSize: size })
}

// Which way an event moves through the scenes: 1 the next, -1 the previous,
// 0 not at all. A swipe across the screen, or one in from an edge, which a
// touch frame's event map makes `forward` (from the right) or `back` (from
// the left); Enter, Space and the right arrow, or the left arrow (a key held
// down does not run through them); a tap or a click.
function stepOf(event: string, payload: any): number {
  if (event === 'forward') return 1
  if (event === 'back') return -1
  if (event === 'swipe') return payload.direction === 'left' ? 1 : payload.direction === 'right' ? -1 : 0
  if (event === 'keyDown') {
    if (payload.repeat || payload.ctrl || payload.alt || payload.meta) return 0
    const code = payload.code
    if (code === 'ArrowLeft') return -1
    return code === 'ArrowRight' || code === 'Enter' || code === 'NumpadEnter' || code === 'Space' ? 1 : 0
  }
  return event === 'tap' ? 1 : 0
}

export function onEvent(app, context) {
  const payload = context.payload || {}
  let step = 0
  if (context.event === 'tap') {
    // The footer's buttons, or the bottom edge of a hidden one, before
    // anything else; a tap on the bar between the buttons does nothing.
    const hit = footerHit(payload.x / size, payload.y / size, footerOn(app.config))
    if (hit === 'hide' || hit === 'show') {
      frameos.setState('footer', hit === 'show')
      return true
    }
    if (hit === 'bar') return false
    if (hit) step = hit === 'next' ? 1 : -1
  }
  if (!step) step = stepOf(context.event, payload)
  if (!step) return false
  const at = ORDER.indexOf(sceneOf(app.config))
  frameos.setState('scene', ORDER[(at + step + ORDER.length) % ORDER.length])
  return true
}

sources.art.ts:
// A scene's picture in the 8-bit palette mode: a byte a cell, each an index
// into 256 colors, some of which cycle. The picture is drawn once; what moves
// afterwards is only the colors, so a frame costs a palette and the panel
// rewrites only the cells whose color changed.
//
// Drawing is the slow part on an ESP32: it has no double-precision FPU and a
// native call (Math.*) from QuickJS costs microseconds, so per-cell loops keep
// to `| 0`, comparisons and values worked out once per row or column.
import { nextInt } from './random'

/** Colors that rotate through their range, `speed` places a second
 *  (negative: the other way); `blend` mixes neighbors for the moments between.
 *  A color moves toward the range's higher entries: lay a range out so its
 *  index grows the way things move (down a waterfall, up a flame). */
export type Cycle = { from: number; count: number; speed: number; blend: boolean }

// The 4x4 ordered-dither matrix, as thresholds in (0, 1).
const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5].map((v) => (v + 0.5) / 16)

export function mix(a: number, b: number, f: number): number {
  const ch = (s: number) => {
    const x = (a >> s) & 255
    return Math.round(x + (((b >> s) & 255) - x) * f) << s
  }
  return ch(16) | ch(8) | ch(0)
}

/** Stops [at (0..1), 0xRRGGBB] read at `at`. */
export function at(stops: number[][], t: number): number {
  let k = 0
  while (k < stops.length - 2 && t > stops[k + 1][0]) k++
  const [a0, c0] = stops[k]
  const [a1, c1] = stops[k + 1]
  return mix(c0, c1, Math.max(0, Math.min(1, a1 === a0 ? 0 : (t - a0) / (a1 - a0))))
}

/** `v` (0..1) as one of `n` levels, dithered by place so a gradient of a few
 *  colors reads as a smooth one. */
export function level(v: number, n: number, x: number, y: number): number {
  // `| 0`, not Math.floor: a native call per cell is a cost on an ESP32, and
  // anything below 0 is clamped either way.
  const l = (v * (n - 1) + BAYER[((y & 3) << 2) | (x & 3)]) | 0
  return l < 0 ? 0 : l >= n ? n - 1 : l
}

// Smoothstep in 1/256ths, as a table.
const SMOOTH = new Uint16Array(256)
for (let i = 0; i < 256; i++) SMOOTH[i] = Math.round(256 * (i / 256) * (i / 256) * (3 - 2 * (i / 256)))

/** Smooth noise in 0..1, `scale` cells to a feature, seeded. Integers inside
 *  but the last division: it runs for every cell of a scene, and an ESP32
 *  has no double-precision FPU, so every float step is a library call there. */
export function noise(scale: number) {
  const g = new Uint8Array(64 * 64)
  for (let i = 0; i < g.length; i++) g[i] = nextInt() >>> 24 // the high byte: xorshift's low bits correlate
  const k = Math.max(1, Math.round(256 / scale))
  return (x: number, y: number) => {
    const xs = (x * k) | 0
    const ys = (y * k) | 0
    const sx = SMOOTH[xs & 255]
    const sy = SMOOTH[ys & 255]
    const r0 = ((ys >> 8) & 63) << 6
    const r1 = (((ys >> 8) + 1) & 63) << 6
    const c0 = (xs >> 8) & 63
    const c1 = ((xs >> 8) + 1) & 63
    const top = (g[r0 | c0] << 8) + (g[r0 | c1] - g[r0 | c0]) * sx
    const bottom = (g[r1 | c0] << 8) + (g[r1 | c1] - g[r1 | c0]) * sx
    return ((top << 8) + (bottom - top) * sy) / 16777216
  }
}

// The footer's two colors, the last two of the 256: a scene's own colors
// stop short of them, so they never cycle and every scene's footer looks alike.
export const BAR = 254
export const INK = 255

export class Art {
  cols: number
  rows: number
  cells: Uint8Array
  colors = new Uint32Array(256)
  used = 0
  cycles: Cycle[] = []

  constructor(cols: number, rows: number) {
    this.cols = cols
    this.rows = rows
    this.cells = new Uint8Array(cols * rows)
    this.colors[BAR] = 0x14121c
    this.colors[INK] = 0xf4efe4
  }

  /** One more color; its index (the last one when the scene's are taken). */
  add(rgb: number): number {
    if (this.used >= BAR) return BAR - 1
    this.colors[this.used] = rgb
    return this.used++
  }

  /** `count` colors through `stops`, still; the first one's index. */
  ramp(count: number, stops: number[][]): number {
    const from = this.used
    for (let i = 0; i < count; i++) this.add(at(stops, count === 1 ? 0 : i / (count - 1)))
    return from
  }

  /** Colors that cycle; the first one's index. */
  cycle(colors: number[], speed: number, blend = true): number {
    const from = this.used
    for (const c of colors) this.add(c)
    this.cycles.push({ from, count: this.used - from, speed, blend })
    return from
  }

  /** Something passing over what is drawn (rain, snow, a star's twinkle):
   *  one cycling range of `count` per color it passes over, entry i of it
   *  `shade(under, i)`. The returned function puts cell `at` on the range for
   *  the color it shows now, at `phase`; a cell whose color has no room left
   *  for a range keeps its color. */
  over(count: number, speed: number, blend: boolean, shade: (under: number, i: number) => number) {
    const ranges = new Map<number, number>()
    return (at: number, phase: number) => {
      const under = this.cells[at]
      let from = ranges.get(under)
      if (from === undefined) {
        if (this.used + count > BAR) return
        const bg = this.colors[under]
        const colors: number[] = []
        for (let i = 0; i < count; i++) colors.push(shade(bg, i))
        from = this.cycle(colors, speed, blend)
        ranges.set(under, from)
      }
      this.cells[at] = from + (((phase % count) + count) % count)
    }
  }

  /** Row `y` from `x0` to `x1` in one of `n` colors from `from`, by `v`
   *  (0..1), dithered: the four levels a row can take worked out once. */
  row(y: number, x0: number, x1: number, from: number, n: number, v: number) {
    const l0 = from + level(v, n, 0, y)
    const l1 = from + level(v, n, 1, y)
    const l2 = from + level(v, n, 2, y)
    const l3 = from + level(v, n, 3, y)
    const cells = this.cells
    const base = y * this.cols
    for (let x = x0; x < x1; x++) {
      const k = x & 3
      cells[base + x] = k === 0 ? l0 : k === 1 ? l1 : k === 2 ? l2 : l3
    }
  }

  /** A filled ellipse of `index` (or `pick(x, y)`), centered at (cx, cy). */
  ellipse(cx: number, cy: number, rx: number, ry: number, index: number | ((x: number, y: number) => number)) {
    const pick = typeof index === 'number' ? null : index
    for (let y = Math.max(0, Math.floor(cy - ry)); y <= Math.min(this.rows - 1, Math.ceil(cy + ry)); y++) {
      for (let x = Math.max(0, Math.floor(cx - rx)); x <= Math.min(this.cols - 1, Math.ceil(cx + rx)); x++) {
        const dx = (x - cx) / rx
        const dy = (y - cy) / ry
        if (dx * dx + dy * dy <= 1) this.cells[y * this.cols + x] = pick ? pick(x, y) : (index as number)
      }
    }
  }

  /** A filled rectangle. */
  rect(x0: number, y0: number, w: number, h: number, index: number) {
    for (let y = Math.max(0, y0); y < Math.min(this.rows, y0 + h); y++) {
      const row = y * this.cols
      this.cells.fill(index, row + Math.max(0, x0), row + Math.min(this.cols, x0 + w))
    }
  }
}

/** The palette at `ms` of cycling: `base` with each range rotated. It runs
 *  every frame, so the blend between two colors is integers inline: on an
 *  ESP32 a call and three Math.round a color were 37 ms of a 68 ms frame. */
export function cycled(art: Art, ms: number, out: Uint32Array) {
  const base = art.colors
  out.set(base)
  for (const c of art.cycles) {
    const n = c.count
    const from = c.from
    let shift = ((ms / 1000) * c.speed) % n
    if (shift < 0) shift += n
    const whole = shift | 0
    const f = c.blend ? ((shift - whole) * 256) | 0 : 0
    // Entry i shows base[i - whole], blended toward base[i - whole - 1].
    let j = n - whole
    if (j >= n) j -= n
    let k = j === 0 ? n - 1 : j - 1
    for (let i = 0; i < n; i++) {
      const a = base[from + j]
      if (f === 0) {
        out[from + i] = a
      } else {
        const b = base[from + k]
        const r = (a >> 16) & 255
        const g = (a >> 8) & 255
        const bl = a & 255
        out[from + i] =
          ((r + ((((b >> 16) & 255) - r) * f >> 8)) << 16) |
          ((g + ((((b >> 8) & 255) - g) * f >> 8)) << 8) |
          (bl + (((b & 255) - bl) * f >> 8))
      }
      k = j
      if (++j === n) j = 0
    }
  }
}

sources.random.ts:
// One xorshift32 for every effect, so a seed is the same picture on every
// frame type. It stays a small integer in QuickJS (no float, no call to
// Math.random in a loop).
let s = 1

export function setSeed(seed: number) {
  s = seed | 0 || 1
}

/** A 32-bit integer. */
export function nextInt(): number {
  s ^= s << 13
  s ^= s >>> 17
  s ^= s << 5
  return s
}

/** A number in [0, 1). */
export function random(): number {
  return (nextInt() >>> 0) / 4294967296
}

/** A number in [lo, hi). */
export function between(lo: number, hi: number): number {
  return lo + random() * (hi - lo)
}

sources.falls.ts:
// Falls: a waterfall at dusk between two cliffs, pouring into a pool. The
// water's streaks, the foam where it lands and the rings across the pool are
// ranges of colors laid down the way they move, and the stars twinkle.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeFalls(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(12, [[0, 0x1b1446], [0.4, 0x4a2468], [0.75, 0xb4527c], [1, 0xf2a06e]])
  const far = art.ramp(3, [[0, 0x3d2a5e], [1, 0x6b3f72]])
  const rock = art.ramp(6, [[0, 0x1c1526], [0.5, 0x3e2b44], [1, 0x7a4f5c]])
  const pine = art.ramp(2, [[0, 0x0d1416], [1, 0x1a2622]])
  const bank = art.ramp(3, [[0, 0x111a17], [1, 0x2c3b2c]])
  const fall = art.cycle([0xffffff, 0xf0faff, 0xdcf1fc, 0xc4e4f7, 0xaad3ef, 0x8fc0e5, 0x77acd9, 0x6a9fd0,
    0x77acd9, 0x8fc0e5, 0xaad3ef, 0xc4e4f7, 0xdcf1fc, 0xeaf7fe, 0xf8fdff, 0xffffff], 20)
  const edge = art.cycle([0x9cc6e6, 0x7aa8d2, 0x5c8bba, 0x4a73a0, 0x3f6694, 0x36598a, 0x3f6694, 0x4a73a0,
    0x5c8bba, 0x6d9cc8, 0x86b6dc, 0xa8cfec], 20)
  const foam = art.cycle([0xffffff, 0xe4f3fc, 0xbcd8ee, 0x8fb8dc, 0x6f9ccb, 0x8fb8dc, 0xc6e0f2, 0xf2faff,
    0xd2e8f6, 0x9cc2e2, 0x7aa6d2, 0xa8cbe8], 6)
  const pool = art.cycle([0x1b3458, 0x203c63, 0x27486f, 0x30567c, 0x3d6688, 0x30567c, 0x27486f, 0x203c63,
    0x1b3458, 0x182f50, 0x162b4a, 0x182f50], 3)

  const horizon = Math.floor(rows * 0.5)
  const n1 = noise(cols / 5)
  const n2 = noise(cols / 9)
  const tex = noise(3)

  // The sky, darkest at the top.
  for (let y = 0; y < rows; y++) art.row(y, 0, cols, sky, 12, Math.min(1, y / horizon))
  // A far range, hazier toward its foot.
  for (let x = 0; x < cols; x++) {
    const top = Math.floor(rows * (0.3 + 0.1 * n1(x, 0)))
    for (let y = top; y < horizon; y++) cells[y * cols + x] = far + level((y - top) / (horizon - top), 3, x, y)
  }

  // The cliffs: a plateau with a notch the water pours through.
  const cx = cols / 2
  const lip = Math.floor(rows * 0.44)
  const poolTop = Math.floor(rows * 0.74)
  const half = (y: number) => cols * (0.06 + 0.025 * Math.max(0, (y - lip) / (poolTop - lip)))
  const cliffTop = new Int32Array(cols)
  // Darker beside the water: how much, by column.
  const shade = new Float64Array(cols)
  for (let x = 0; x < cols; x++) {
    const d = 1 - (x > cx ? x - cx : cx - x) / (cols * 0.16)
    shade[x] = d > 0 ? 0.35 * d : 0
  }
  for (let x = 0; x < cols; x++) {
    const away = Math.abs(x - cx) / cols
    cliffTop[x] = Math.floor(rows * (0.42 + 0.05 * n2(x, 3) - 0.1 * Math.min(1, away * 2.2)) + (away < 0.09 ? rows * 0.02 : 0))
    // Lit from the sunset above: lighter near the top edge, strata across.
    const top = cliffTop[x]
    const fall = 0.7 / (poolTop - top)
    const lit = 0.9 - shade[x] - 0.225
    for (let y = top; y < poolTop; y++) {
      cells[y * cols + x] = rock + level(lit - fall * (y - top) + 0.45 * tex(x * 0.8, y * 2.5), 6, x, y)
    }
  }
  // Pines along the edge.
  for (let x = 2; x < cols - 2; x += 2 + Math.floor(random() * 4)) {
    if (Math.abs(x - cx) < cols * 0.1) continue
    const h = Math.floor(rows * (0.03 + 0.05 * random()))
    const base = cliffTop[x] + 1
    for (let k = 0; k < h; k++) {
      const w = Math.floor((k / h) * h * 0.35)
      for (let dx = -w; dx <= w; dx++) {
        const xx = x + dx
        if (xx >= 0 && xx < cols && base - h + k >= 0) cells[(base - h + k) * cols + xx] = pine + (dx < 0 ? 1 : 0)
      }
    }
  }

  // The water: streaks down the fall, each column at its own offset, so the
  // range rotating reads as water falling. Darker at its sides.
  const offsets = new Int32Array(cols + 1)
  for (let x = 0; x < cols; x += 2) offsets[x] = offsets[x + 1] = Math.floor(random() * 16)
  for (let y = lip; y < poolTop + 2; y++) {
    const w = half(y)
    for (let x = Math.floor(cx - w); x <= Math.ceil(cx + w); x++) {
      const side = Math.abs(x - cx) / w
      const at = y * cols + x
      if (side > 1) continue
      cells[at] = side > 0.82 ? edge + (((y + offsets[x]) % 12) + 12) % 12 : fall + (((y + offsets[x]) % 16) + 16) % 16
    }
  }

  // The pool, rings spreading from where the water lands.
  // Distances squared in ring widths, by column and by row; one square root
  // a cell, and the left half of a row mirrors the right's.
  const across = new Float64Array(cols)
  for (let x = 0; x < cols; x++) across[x] = ((x - cx) * 0.5) * ((x - cx) * 0.5)
  for (let y = poolTop; y < rows; y++) {
    const dy = ((y - poolTop) / rows) * 3.2 * cols * 0.5
    const down = dy * dy
    for (let x = 0; x < cols; x++) {
      cells[y * cols + x] = pool + (((Math.sqrt(across[x] + down) + 2.5 * tex(x, y * 2)) | 0) % 12)
    }
  }
  // Banks of rock and grass in the corners.
  for (let x = 0; x < cols; x++) {
    const away = Math.abs(x - cx) / cols
    const top = Math.floor(rows * (1.12 - away * 0.7) + 4 * n1(x * 3, 9))
    for (let y = Math.max(poolTop, top); y < rows; y++) {
      cells[y * cols + x] = bank + level(0.95 - (y - top) / (rows * 0.3) + 0.4 * (tex(x * 3, y * 3) - 0.5), 3, x, y)
    }
  }
  // Foam where it lands, churning outward.
  const foamW = cols * 0.17
  const foamH = rows * 0.05
  for (let y = poolTop - 2; y < poolTop + foamH; y++) {
    for (let x = Math.floor(cx - foamW); x <= Math.ceil(cx + foamW); x++) {
      const dx = (x - cx) / foamW
      const dy = (y - poolTop) / foamH
      const d = Math.sqrt(dx * dx + dy * dy * (dy < 0 ? 6 : 1))
      if (d > 0.75 + 0.35 * tex(x * 3, y * 3)) continue
      cells[y * cols + x] = foam + (((d * 10 + 4 * tex(x * 2.5, y * 2.5)) | 0) % 12)
    }
  }

  // Stars over the darkest of the sky, each at its own point of a slow twinkle.
  const twinkle = art.over(10, 2.5, true, (under, i) =>
    i === 4 ? mix(under, 0xffffff, 0.95) : i === 3 || i === 5 ? mix(under, 0xffffff, 0.45) : under)
  for (let i = Math.floor((cols * rows) / 300); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * rows * 0.3)
    if (y < cliffTop[x] - 2) twinkle(y * cols + x, Math.floor(random() * 10))
  }

  return art
}

sources.harbor.ts:
// Harbor: the sun going down over the sea. Waves roll in as bands of color
// laid from the horizon to the shore, the sun's path glitters, and the
// lighthouse on the point breathes its light.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeHarbor(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(14, [[0, 0x19244f], [0.35, 0x473a78], [0.7, 0xd0646a], [0.9, 0xf59a62], [1, 0xffc879]])
  const cloud = art.ramp(4, [[0, 0x6a3f6e], [0.5, 0xc25f6c], [1, 0xffa877]])
  const sun = art.ramp(3, [[0, 0xffd27a], [1, 0xfff6d8]])
  const land = art.ramp(3, [[0, 0x0f1020], [1, 0x2a2238]])
  const tower = art.ramp(3, [[0, 0x8a7f96], [0.5, 0xd8cfd8], [1, 0xfff3ea]])
  const band = art.add(0x9a2f45)
  const dark = art.add(0x14131f)
  const farSea = art.cycle([0x6b4a7e, 0x7a5584, 0x8b6088, 0x9a6a8a, 0x8b6088, 0x7a5584, 0x6b4a7e, 0x5f4277,
    0x553c70, 0x4d376a, 0x553c70, 0x5f4277], 3)
  const nearSea = art.cycle([0x2b3e6e, 0x324a7a, 0x3b5687, 0x476592, 0x5a789f, 0x476592, 0x3b5687, 0x324a7a,
    0x2b3e6e, 0x26376a, 0x223163, 0x26376a], 3)
  const glitter = art.cycle([0xfff0b0, 0xffc56e, 0xd8805e, 0x8e5a72, 0x5d4878, 0x8e5a72, 0xd8805e, 0xffc56e,
    0xffe08e, 0xe89a62, 0xa56470, 0x6b4f7a], 7, false)
  const lamp = art.cycle([0x3a2a2a, 0x5a3a2a, 0x8a5a2a, 0xc8862e, 0xffc24a, 0xffeaa0, 0xffffff, 0xffeaa0,
    0xffc24a, 0xc8862e, 0x8a5a2a, 0x5a3a2a, 0x3a2a2a, 0x3a2a2a, 0x3a2a2a, 0x3a2a2a], 5)

  const horizon = Math.floor(rows * 0.56)
  const n = noise(cols / 6)
  const tex = noise(4)
  const sunX = cols * 0.64
  const sunY = horizon - rows * 0.02
  const sunR = Math.min(cols, rows) * 0.08

  for (let y = 0; y < horizon; y++) art.row(y, 0, cols, sky, 14, y / horizon)
  // The sun's glow, where there is any: within its box only.
  for (let y = Math.max(0, Math.floor(sunY - rows / 2.2)); y < horizon; y++) {
    const dy = (y - sunY) / rows
    for (let x = Math.max(0, Math.floor(sunX - cols / 2.2)); x < Math.min(cols, sunX + cols / 2.2); x++) {
      const dx = (x - sunX) / cols
      const d2 = dx * dx + dy * dy
      if (d2 >= 0.2066) continue // past 1 / 2.2: no glow
      const glow = (1 - Math.sqrt(d2) * 2.2) * 0.25
      cells[y * cols + x] = sky + level(y / horizon + glow, 14, x, y)
    }
  }
  // Long thin clouds, lit from below.
  for (let y = Math.floor(rows * 0.12); y < horizon - rows * 0.08; y++) {
    for (let x = 0; x < cols; x++) {
      const v = n(x * 0.5, y * 4) * 0.7 + tex(x, y * 3) * 0.3
      if (v > 0.62) cells[y * cols + x] = cloud + level((v - 0.62) * 3 + (y / horizon) * 0.6, 4, x, y)
    }
  }
  // The sun, half under.
  art.ellipse(sunX, sunY, sunR, sunR, (x, y) => (y < horizon ? sun + level(1 - Math.hypot(x - sunX, y - sunY) / sunR, 3, x, y) : cells[y * cols + x]))

  // The sea: the farther a row, the thinner its waves; the bands' index grows
  // toward the shore, so the cycle rolls them in.
  for (let y = horizon; y < rows; y++) {
    const z = (y - horizon + 1) / (rows - horizon)
    const bands = Math.sqrt(z) * 34
    const sea = z < 0.3 ? farSea : nearSea
    for (let x = 0; x < cols; x++) cells[y * cols + x] = sea + (((bands + 2.5 * tex(x * 0.4, y * 1.5)) | 0) % 12)
  }
  // The sun's path on the water.
  for (let y = horizon; y < rows; y++) {
    const z = (y - horizon + 1) / (rows - horizon)
    const w = cols * (0.02 + 0.12 * z)
    for (let x = Math.floor(sunX - w); x <= sunX + w; x++) {
      if (x < 0 || x >= cols) continue
      const near = 1 - Math.abs(x - sunX) / w
      if (random() < near * near * (0.8 - 0.4 * z)) cells[y * cols + x] = glitter + Math.floor(random() * 12)
    }
  }

  // The point, its lighthouse and a boat.
  const pointX = cols * 0.34
  for (let x = 0; x < pointX; x++) {
    const top = Math.floor(horizon - rows * 0.04 + rows * 0.08 * (x / pointX) ** 2 - rows * 0.05 * n(x * 2, 5))
    for (let y = top; y < rows; y++) {
      if (y > horizon + rows * 0.03 * (1 - x / pointX)) break
      cells[y * cols + x] = land + level(0.6 - (y - top) / (rows * 0.3) + 0.4 * (tex(x * 2, y * 2) - 0.5), 3, x, y)
    }
  }
  const tx = Math.floor(cols * 0.14)
  const tw = Math.max(3, Math.floor(cols * 0.045))
  const tTop = Math.floor(horizon - rows * 0.24)
  const tBase = Math.floor(horizon - rows * 0.03)
  for (let y = tTop; y < tBase; y++) {
    const w = tw * (0.75 + 0.25 * (y - tTop) / (tBase - tTop))
    const stripe = Math.floor(((y - tTop) / (tBase - tTop)) * 5) % 2 === 1
    for (let x = Math.floor(tx - w / 2); x < tx + w / 2; x++) {
      const side = (x - (tx - w / 2)) / w
      cells[y * cols + x] = stripe ? band : tower + level(1 - side, 3, x, y)
    }
  }
  art.rect(tx - Math.floor(tw / 2) - 1, tTop - 1, tw + 2, 1, dark)
  art.rect(tx - Math.floor(tw / 2), tTop - Math.floor(tw * 0.8) - 1, tw, Math.floor(tw * 0.8), lamp)
  art.rect(tx - Math.floor(tw / 2) - 1, tTop - Math.floor(tw * 0.8) - 2, tw + 2, 1, dark)
  // The boat: a hull and two sails against the glitter.
  const bx = Math.floor(cols * 0.8)
  const by = Math.floor(horizon + rows * 0.06)
  const bs = Math.max(4, Math.floor(cols * 0.06))
  for (let k = 0; k < bs; k++) {
    for (let x = bx - Math.floor(k * 0.55); x <= bx; x++) cells[(by - bs + k) * cols + x] = dark
    for (let x = bx + 1; x <= bx + 1 + Math.floor(k * 0.35); x++) cells[(by - bs + k) * cols + x] = dark
  }
  art.rect(bx - Math.floor(bs * 0.7), by, Math.floor(bs * 1.4), Math.max(1, Math.floor(bs / 4)), dark)
  // A few stars before dark.
  const twinkle = art.over(10, 2, true, (under, i) => (i === 4 ? mix(under, 0xffffff, 0.8) : i === 3 || i === 5 ? mix(under, 0xffffff, 0.35) : under))
  for (let i = Math.floor((cols * rows) / 900); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * rows * 0.15)
    twinkle(y * cols + x, Math.floor(random() * 10))
  }
  return art
}

