// Rain: a village on a hill on a wet night. The rain falls along slanted
// tracks, one range of colors for each color it falls past, puddles ring
// where the drops land, and a window or two flickers.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeRain(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(6, [[0, 0x0b1020], [1, 0x27304a]])
  const cloud = art.ramp(3, [[0, 0x1e2538], [1, 0x3b4560]])
  const hill = art.ramp(3, [[0, 0x0c1418], [1, 0x1d2a2c]])
  const wall = art.ramp(3, [[0, 0x1a1a24], [1, 0x34303c]])
  const roof = art.ramp(2, [[0, 0x150f16], [1, 0x2c1f26]])
  const road = art.ramp(4, [[0, 0x14161e], [1, 0x3a3640]])
  const glow = art.ramp(5, [[0, 0x2a2a34], [0.6, 0x6a5440], [1, 0xd8a85a]])
  const window = art.add(0xffcf6a)
  const lampHead = art.add(0xfff2c0)
  const post = art.add(0x0a0a0e)
  const flicker = art.cycle([0xffcf6a, 0xffc860, 0xf2b858, 0xffd476, 0xe8a850, 0xffcf6a, 0xffe090, 0xf6bc5c], 3, false)
  const puddle = art.cycle([0x3a3e4c, 0x4c5262, 0x6a6e7c, 0x4c5262, 0x3a3e4c, 0x30343f, 0x2c303a, 0x30343f], 5)

  const ground = Math.floor(rows * 0.72)
  const n = noise(cols / 4)
  const tex = noise(3)
  for (let y = 0; y < rows; y++) art.row(y, 0, cols, sky, 6, y / ground)
  for (let y = 0; y < rows * 0.4; y++) {
    for (let x = 0; x < cols; x++) {
      const v = n(x * 0.6, y * 1.5)
      if (v > 0.55) cells[y * cols + x] = cloud + level((v - 0.55) * 3, 3, x, y)
    }
  }
  // The hill the village sits on.
  const hillTop = new Int32Array(cols)
  for (let x = 0; x < cols; x++) {
    hillTop[x] = Math.floor(rows * (0.5 + 0.08 * Math.cos((x / cols - 0.4) * 3)) + rows * 0.04 * n(x, 7))
    for (let y = hillTop[x]; y < ground; y++) cells[y * cols + x] = hill + level((y - hillTop[x]) / (rows * 0.3), 3, x, y)
  }
  // Houses along the hill, windows lit.
  const flickering = new Set([1, 4])
  let k = 0
  for (let x = Math.floor(cols * 0.04); x < cols * 0.92; k++) {
    const w = Math.floor(cols * (0.08 + 0.05 * random()))
    const h = Math.floor(rows * (0.07 + 0.05 * random()))
    const base = Math.min(hillTop[x], hillTop[Math.min(cols - 1, x + w)]) + Math.floor(rows * 0.04)
    art.rect(x, base - h, w, h, wall + Math.floor(random() * 3))
    const peak = Math.floor(w * 0.45)
    for (let r = 0; r < peak; r++) {
      const rw = Math.max(1, Math.round(((w + 2) * (r + 1)) / peak))
      art.rect(x + ((w - rw) >> 1), base - h - peak + r, rw, 1, roof + (r % 3 === 0 ? 1 : 0))
    }
    for (let wx = x + 2; wx < x + w - 2; wx += 4) {
      if (random() < 0.3) continue
      art.rect(wx, base - h + 2, 2, 2, flickering.has(k) ? flicker + Math.floor(random() * 8) : window)
    }
    x += w + 2 + Math.floor(random() * cols * 0.06)
  }
  // The road, a lamp and its pool of light.
  const lampX = Math.floor(cols * 0.7)
  const lampY = Math.floor(ground - rows * 0.2)
  for (let y = ground; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const dx = (x - lampX) / cols
      const dy = ((y - ground) / rows) * 2.5
      const near = dx > -0.34 && dx < 0.34 ? dx * dx + dy * dy : 1
      const lit = near < 0.111 ? (1 - Math.sqrt(near) * 3) * 0.7 : 0
      cells[y * cols + x] = road + level(0.3 + 0.3 * (tex(x * 1.5, y * 4) - 0.5) + lit, 4, x, y)
    }
  }
  for (let y = lampY - rows * 0.08; y < ground + 2; y++) {
    for (let x = lampX - cols * 0.12; x < lampX + cols * 0.12; x++) {
      const xi = Math.floor(x)
      const yi = Math.floor(y)
      const d = Math.hypot((xi - lampX) / cols, (yi - lampY) / rows) * 7
      if (d < 1 && cells[yi * cols + xi] < hill + 3) cells[yi * cols + xi] = glow + level((1 - d) * 0.9, 5, xi, yi)
    }
  }
  art.rect(lampX, lampY, 1, ground - lampY + 2, post)
  art.rect(lampX - 1, lampY - 2, 3, 2, lampHead)
  // Puddles, ringing.
  for (let i = 0; i < 4; i++) {
    const px = cols * (0.1 + 0.8 * random())
    const py = ground + (rows - ground) * (0.3 + 0.6 * random())
    const rx = cols * (0.06 + 0.05 * random())
    art.ellipse(px, py, rx, rx * 0.25, (x, y) => puddle + (Math.floor(Math.hypot(x - px, (y - py) * 4) * 0.7) % 8))
  }

  // The rain: tracks slanting down to the right, a drop every 9 cells.
  // A range's colors move toward its higher entries, so a track's phase grows
  // downward: the drop is entry 0 and its trail the two before it, above.
  const rain = art.over(14, 30, false, (under, i) =>
    i === 0 ? mix(under, 0xc4d0e6, 0.6) : i >= 12 ? mix(under, 0xa8b6d0, 0.35) : under)
  for (let x0 = -Math.floor(rows / 4); x0 < cols; x0 += 4 + Math.floor(random() * 4)) {
    const offset = Math.floor(random() * 14)
    for (let y = 0; y < rows; y++) {
      const x = x0 + Math.floor(y / 4)
      if (x >= 0 && x < cols) rain(y * cols + x, offset + y)
    }
  }
  return art
}

sources.snow.ts:
// Snow: a cabin in the hills under the moon. Flakes drift down their own
// wavering tracks, smoke rises from the chimney, the windows glow and the
// stars twinkle.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeSnow(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(7, [[0, 0x060b1e], [0.6, 0x15264a], [1, 0x2c4a6e]])
  const moon = art.ramp(3, [[0, 0xc9d6e8], [1, 0xf6f8ff]])
  const halo = art.ramp(2, [[0, 0x203658], [1, 0x2c4670]])
  const snow = art.ramp(5, [[0, 0x4a6488], [0.5, 0x8aa4c6], [1, 0xe4eefa]])
  const pine = art.ramp(2, [[0, 0x08130f], [1, 0x14251c]])
  const log = art.ramp(3, [[0, 0x2a1810], [1, 0x5a3420]])
  const window = art.cycle([0xffc860, 0xffd27a, 0xf6b850, 0xffd27a, 0xffc860, 0xffe29a], 2, true)
  const stone = art.add(0x3a3a44)

  const n = noise(cols / 5)
  const tex = noise(3)
  for (let y = 0; y < rows; y++) art.row(y, 0, cols, sky, 7, y / (rows * 0.7))
  const mx = cols * 0.78
  const my = rows * 0.18
  const mr = Math.min(cols, rows) * 0.06
  art.ellipse(mx, my, mr * 2.2, mr * 2.2, (x, y) => halo + level(1 - Math.hypot(x - mx, y - my) / (mr * 2.2), 2, x, y))
  art.ellipse(mx, my, mr, mr, (x, y) => moon + level(0.4 + 0.6 * tex(x * 2, y * 2), 3, x, y))

  // Two ridges of snow, the far one bluer.
  const near = new Int32Array(cols)
  for (let x = 0; x < cols; x++) {
    const far = Math.floor(rows * (0.5 + 0.08 * n(x, 1)))
    near[x] = Math.floor(rows * (0.66 + 0.06 * n(x * 1.4, 5)))
    for (let y = far; y < near[x]; y++) cells[y * cols + x] = snow + level(0.3 - (y - far) / rows, 5, x, y)
    for (let y = near[x]; y < rows; y++) cells[y * cols + x] = snow + level(0.89 - (y - near[x]) / (rows * 0.5) + 0.12 * tex(x * 0.5, y), 5, x, y)
  }
  // Pines with snow on their boughs.
  const tree = (x: number, base: number, h: number) => {
    for (let k = 0; k < h; k++) {
      const w = Math.floor(k * 0.4 * ((k % 4) / 4 + 0.6))
      for (let dx = -w; dx <= w; dx++) {
        const xx = x + dx
        const yy = base - h + k
        if (xx < 0 || xx >= cols || yy < 0) continue
        cells[yy * cols + xx] = k % 4 === 0 && Math.abs(dx) < w ? snow + 4 : pine + (dx < 0 ? 0 : 1)
      }
    }
  }
  for (let x = 1; x < cols; x += 3 + Math.floor(random() * 6)) {
    if (x > cols * 0.3 && x < cols * 0.62) continue
    tree(x, near[x] + 2, Math.floor(rows * (0.08 + 0.1 * random())))
  }

  // The cabin.
  const cx = Math.floor(cols * 0.46)
  const cw = Math.floor(cols * 0.2)
  const base = near[cx] + Math.floor(rows * 0.04)
  const ch = Math.floor(rows * 0.1)
  for (let y = base - ch; y < base; y++) art.rect(cx - (cw >> 1), y, cw, 1, log + ((y - base) % 2 === 0 ? 0 : 2))
  const peak = Math.floor(cw * 0.6)
  for (let r = 0; r < peak; r++) {
    const w = Math.max(1, Math.round(((cw + 4) * (r + 1)) / peak))
    art.rect(cx - (w >> 1), base - ch - peak + r, w, 1, r > peak - 3 ? snow + 2 : snow + 4 - (r % 3 === 0 ? 1 : 0))
  }
  const chimX = cx + Math.floor(cw * 0.22)
  const chimTop = base - ch - Math.floor(peak * 0.7)
  art.rect(chimX, chimTop, 3, Math.floor(peak * 0.6), stone)
  art.rect(cx - Math.floor(cw * 0.3), base - Math.floor(ch * 0.7), 4, 3, window)
  art.rect(cx + Math.floor(cw * 0.12), base - Math.floor(ch * 0.7), 4, 3, window + 2)
  art.rect(cx - 1, base - Math.floor(ch * 0.55), 3, Math.floor(ch * 0.55), log)

  // Smoke rising, curling to the right as it goes: a range's colors move
  // toward its higher entries, so the phase grows upward (and the flakes'
  // below, downward).
  const smoke = art.over(12, 6, true, (under, i) => mix(under, 0xaab4c6, Math.max(0, 0.6 - Math.abs(i - 3) * 0.13)))
  for (let up = 1; up < rows * 0.35; up++) {
    const y = chimTop - up
    if (y < 0) break
    const sway = Math.sin(up * 0.18) * (1 + up * 0.06) + up * 0.25
    const w = 1 + Math.floor(up * 0.08)
    for (let dx = -w; dx <= w; dx++) {
      const x = Math.floor(chimX + 1 + sway + dx)
      if (x >= 0 && x < cols && random() < 1 - up / (rows * 0.4)) smoke(y * cols + x, up + Math.floor(random() * 2))
    }
  }
  // Snowfall, the tracks wavering.
  const flake = art.over(14, 7, false, (under, i) => (i === 0 ? mix(under, 0xffffff, 0.85) : under))
  for (let x0 = 0; x0 < cols; x0 += 3 + Math.floor(random() * 3)) {
    const offset = Math.floor(random() * 14)
    const phase = random() * 6
    for (let y = 0; y < rows; y++) {
      const x = Math.floor(x0 + 1.5 * Math.sin(y * 0.12 + phase))
      if (x >= 0 && x < cols) flake(y * cols + x, offset + y)
    }
  }
  const twinkle = art.over(8, 2, true, (under, i) => (i === 3 ? mix(under, 0xffffff, 0.8) : i === 2 || i === 4 ? mix(under, 0xffffff, 0.3) : under))
  for (let i = Math.floor((cols * rows) / 500); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * rows * 0.4)
    if (cells[y * cols + x] < sky + 7) twinkle(y * cols + x, Math.floor(random() * 8))
  }
  return art
}

sources.aurora.ts:
// Aurora: the northern lights over a still lake. The curtains are ranges of
// green to violet laid across the sky, brighter toward their foot, and their
// waves run along them; the lake holds them again between its ripples.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeAurora(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(6, [[0, 0x03050d], [1, 0x0f1d33]])
  const ridge = art.ramp(2, [[0, 0x05080e], [1, 0x0d1520]])
  const pine = art.add(0x020405)
  const water = art.ramp(3, [[0, 0x050a14], [1, 0x0e1a2c]])
  // Four curtains by height, each a wave of brightness to run along it.
  const curtains: number[] = []
  const tones = [0x5effa6, 0x3fd6b0, 0x3d8fc8, 0x8a5ad6]
  for (let k = 0; k < 4; k++) {
    const colors: number[] = []
    for (let i = 0; i < 16; i++) {
      const wave = 0.5 + 0.5 * Math.cos((i / 16) * Math.PI * 2)
      colors.push(mix(0x0a1424, tones[k], (0.25 + 0.75 * wave) * (1 - k * 0.18)))
    }
    curtains.push(art.cycle(colors, 4 + k))
  }

  const horizon = Math.floor(rows * 0.6)
  const n = noise(cols / 3)
  const tex = noise(5)
  for (let y = 0; y < horizon; y++) art.row(y, 0, cols, sky, 6, y / horizon)
  // The curtains: a foot that wanders, a height that varies, rays upward.
  for (let x = 0; x < cols; x++) {
    const foot = horizon * (0.62 + 0.18 * n(x, 0))
    const height = horizon * (0.25 + 0.3 * n(x * 0.7, 9))
    const ray = tex(x * 3, 0)
    for (let y = Math.max(0, Math.floor(foot - height)); y < foot; y++) {
      const up = (foot - y) / height // 0 at the foot, 1 at the top
      if (random() > 1.1 - up * up + ray * 0.2) continue
      const band = (up * 4 + 0.6 * random() - 0.3) | 0
      cells[y * cols + x] = curtains[band > 3 ? 3 : band < 0 ? 0 : band] + (((x * 0.6 + 8 * n(x * 0.5, y * 0.05)) | 0) % 16)
    }
  }
  // Stars where the lights are not.
  const twinkle = art.over(9, 2.2, true, (under, i) => (i === 4 ? mix(under, 0xffffff, 0.85) : i === 3 || i === 5 ? mix(under, 0xffffff, 0.35) : under))
  for (let i = Math.floor((cols * rows) / 250); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * horizon * 0.9)
    if (cells[y * cols + x] < sky + 6) twinkle(y * cols + x, Math.floor(random() * 9))
  }
  // Hills and pines along the far shore.
  const shore = new Int32Array(cols)
  for (let x = 0; x < cols; x++) {
    const top = Math.floor(horizon - rows * (0.04 + 0.06 * n(x * 1.5, 4)))
    shore[x] = top
    for (let y = top; y < horizon; y++) cells[y * cols + x] = ridge + level((y - top) / (horizon - top), 2, x, y)
  }
  for (let x = 0; x < cols; x += 1 + Math.floor(random() * 3)) {
    const h = Math.floor(rows * (0.02 + 0.04 * random()))
    for (let k = 0; k < h; k++) {
      const w = Math.floor(k * 0.3)
      art.rect(x - w, shore[x] - h + k, 2 * w + 1, 1, pine)
    }
  }
  // The lake: the sky again, upside down, under dark ripples.
  for (let y = horizon; y < rows; y++) {
    const from = 2 * horizon - y - 1
    const lines = (y - horizon) < rows * 0.15 ? 2 : 3
    const spread = 1 + (y - horizon) / (rows * 0.1)
    for (let x = 0; x < cols; x++) {
      const wobble = (2 * (tex(x * 0.5, y * 3) - 0.5) * spread) | 0
      const sx = x + wobble < 0 ? 0 : x + wobble >= cols ? cols - 1 : x + wobble
      const mirrored = from >= 0 ? cells[from * cols + sx] : sky
      const dark = (y - horizon) % lines === 0 || from < 0 || mirrored < curtains[0] && mirrored >= sky + 6
      cells[y * cols + x] = dark ? water + level(0.3 + (y - horizon) / rows, 3, x, y) : mirrored
    }
  }
  return art
}

