// Campfire: a clearing in the woods at night. The flames are ranges of color
// laid from the embers up, so they lick upward; sparks climb above them,
// fireflies blink at the edge of the trees.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeCampfire(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(5, [[0, 0x050711], [1, 0x141a2e]])
  const trees = art.ramp(3, [[0, 0x040806], [1, 0x0e1712]])
  const ground = art.ramp(8, [[0, 0x0c0d10], [0.5, 0x3a2418], [1, 0xa45a26]])
  const tent = art.ramp(4, [[0, 0x1a1418], [0.6, 0x6a3a22], [1, 0xc0702e]])
  const wood = art.ramp(3, [[0, 0x1e120c], [1, 0x5a3218]])
  const stone = art.ramp(3, [[0, 0x1c1a1e], [1, 0x6a5a52]])
  const core = art.cycle([0xfff6c8, 0xffe08a, 0xffc24a, 0xffa030, 0xffc24a, 0xffe08a, 0xffeeb0, 0xffd06a,
    0xffb03c, 0xff9428, 0xffb03c, 0xffd06a], 14, false)

  const groundY = Math.floor(rows * 0.62)
  const fx = cols * 0.5
  const fy = rows * 0.8
  const n = noise(cols / 6)
  const tex = noise(3)
  for (let y = 0; y < groundY; y++) art.row(y, 0, cols, sky, 5, y / groundY)
  // The treeline: pines against the sky, lit a little from the fire.
  for (let x = 0; x < cols; x += 1 + Math.floor(random() * 3)) {
    const h = Math.floor(rows * (0.25 + 0.25 * n(x, 2) + 0.08 * random()))
    for (let k = 0; k < h; k++) {
      const w = Math.floor(k * 0.28 * (0.7 + 0.3 * ((k % 5) / 5)))
      art.rect(x - w, groundY - h + k + 2, 2 * w + 1, 1, trees + (k % 7 === 0 ? 1 : 0))
    }
  }
  // The ground, warmest round the fire.
  const across = new Float64Array(cols)
  for (let x = 0; x < cols; x++) across[x] = ((x - fx) / cols) * ((x - fx) / cols)
  for (let y = groundY; y < rows; y++) {
    const dy = ((y - fy) / rows) * 1.8
    const down = dy * dy
    for (let x = 0; x < cols; x++) {
      const warm = 1 - Math.sqrt(across[x] + down) * 2.4
      cells[y * cols + x] = ground + level((warm > 0 ? warm : 0) + 0.25 * tex(x * 2, y * 2) - 0.125, 8, x, y)
    }
  }
  // A tent, lit on the side facing the fire.
  const tx = cols * 0.2
  const tBase = Math.floor(rows * 0.74)
  const th = Math.floor(rows * 0.17)
  for (let k = 0; k < th; k++) {
    const w = Math.floor(k * 0.9)
    for (let dx = -w; dx <= w; dx++) {
      const x = Math.floor(tx + dx)
      const lit = dx > 0 ? 0.55 + 0.45 * (dx / (w + 1)) : 0.2 - 0.2 * (-dx / (w + 1))
      if (x >= 0 && x < cols) cells[(tBase - th + k) * cols + x] = Math.abs(dx) < k * 0.12 ? tent : tent + level(lit, 4, x, k)
    }
  }
  // Stones in a ring, logs crossed.
  for (let a = 0; a < 12; a++) {
    const sx = fx + Math.cos((a / 12) * Math.PI * 2) * cols * 0.09
    const sy = fy + 1 + Math.sin((a / 12) * Math.PI * 2) * rows * 0.025
    art.ellipse(sx, sy, cols * 0.017, rows * 0.012, (x, y) => stone + level(Math.sin((a / 12) * Math.PI * 2) * -0.4 + 0.6 - (y - sy) * 0.2, 3, x, y))
  }
  for (let k = -1; k <= 1; k += 2) {
    for (let i = -cols * 0.07; i < cols * 0.07; i++) {
      const x = Math.floor(fx + i)
      const y = Math.floor(fy - 1 + i * 0.25 * k)
      art.rect(x, y, 1, 2, wood + (i % 3 === 0 ? 2 : 1))
    }
  }
  // The flames: a teardrop, the index climbing from the embers, so the colors
  // lick upward; the outside of it comes and goes against the night.
  const flameH = rows * 0.2
  const flameW = cols * 0.075
  const outer = art.over(12, 14, false, (under, i) =>
    i < 3 ? 0xff8a24 : i < 5 ? 0xd2541a : i < 6 ? mix(under, 0x9a3010, 0.6) : under)
  for (let y = Math.floor(fy - flameH); y < fy; y++) {
    const up = (fy - y) / flameH // 0 at the embers, 1 at the tip
    const w = flameW * Math.pow(1 - up, 0.8) * Math.min(1, 0.55 + up * 4) * (0.8 + 0.4 * tex(3, y * 0.6))
    for (let x = Math.floor(fx - w - 2); x <= fx + w + 2; x++) {
      const side = Math.abs(x - fx) / Math.max(1, w)
      const lick = Math.floor((fy - y) + 5 * tex(x * 1.6, 0))
      if (side < 0.6 - up * 0.4) cells[y * cols + x] = core + ((lick % 12) + 12) % 12
      else if (side < 1.15) outer(y * cols + x, lick)
    }
  }
  // Sparks climbing over the flames.
  // Phase grows upward, the way they go; the glow trails below each spark.
  const spark = art.over(16, 9, false, (under, i) => (i === 0 ? 0xffd27a : i === 15 ? mix(under, 0xff8a30, 0.6) : under))
  for (let s = 0; s < 7; s++) {
    let x = fx + (random() - 0.5) * flameW
    const offset = Math.floor(random() * 16)
    for (let y = Math.floor(fy - flameH); y > fy - flameH - rows * 0.25; y--) {
      x += (random() - 0.4) * 0.8
      const xi = Math.floor(x)
      if (y >= 0 && xi >= 0 && xi < cols) spark(y * cols + xi, offset - y)
    }
  }
  // Fireflies at the edge of the trees.
  const blink = art.over(12, 1.5, true, (under, i) => (i === 5 ? 0xd8ff7a : i === 4 || i === 6 ? mix(under, 0xb8e060, 0.45) : under))
  for (let i = 0; i < 14; i++) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(groundY - rows * 0.15 + random() * rows * 0.2)
    if (Math.abs(x - fx) > cols * 0.15) blink(y * cols + x, Math.floor(random() * 12))
  }
  const twinkle = art.over(8, 2, true, (under, i) => (i === 3 ? mix(under, 0xffffff, 0.75) : under))
  for (let i = Math.floor((cols * rows) / 600); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * rows * 0.25)
    if (cells[y * cols + x] < sky + 5) twinkle(y * cols + x, Math.floor(random() * 8))
  }
  return art
}

sources.font.ts:
// A 3x5 font, 15 bits a glyph, top row first: the footer is drawn with it,
// a cell a dot.
export const GLYPHS: Record<string, number> = {
  A: 0x2bed, B: 0x6bae, C: 0x3923, D: 0x6b6e, E: 0x79a7, F: 0x79a4, G: 0x396b, H: 0x5bed, I: 0x7497,
  J: 0x126a, K: 0x5bad, L: 0x4927, M: 0x5fed, N: 0x6b6d, O: 0x2b6a, P: 0x6ba4, Q: 0x2b73, R: 0x6bad,
  S: 0x388e, T: 0x7492, U: 0x5b6f, V: 0x5b6a, W: 0x5bfd, X: 0x5aad, Y: 0x5a92, Z: 0x72a7,
  0: 0x7b6f, 1: 0x2c97, 2: 0x73e7, 3: 0x73cf, 4: 0x5bc9, 5: 0x79cf, 6: 0x79ef, 7: 0x7249, 8: 0x7bef, 9: 0x7bcf,
  '-': 0x01c0, '+': 0x05d0, '<': 0x1511, '>': 0x4454, '.': 0x0002, ':': 0x0410, '/': 0x12a4, ' ': 0,
}

/** Cells `text` takes at `scale`: 4 a letter (3 and a gap), less the last gap. */
export function textWidth(text: string, scale: number): number {
  return Math.max(0, text.length * 4 - 1) * scale
}

/** One glyph's dots into `cells` (a grid `cols` wide) at (x, y), `value` each. */
export function drawGlyph(cells: any, cols: number, rows: number, bits: number, x: number, y: number,
    scale: number, value: number) {
  for (let i = 0; i < 15; i++) {
    if (!(bits & (1 << (14 - i)))) continue
    const left = x + (i % 3) * scale
    const top = y + ((i / 3) | 0) * scale
    for (let dy = 0; dy < scale; dy++) {
      const yy = top + dy
      if (yy < 0 || yy >= rows) continue
      for (let dx = 0; dx < scale; dx++) {
        const xx = left + dx
        if (xx >= 0 && xx < cols) cells[yy * cols + xx] = value
      }
    }
  }
}

export function drawText(cells: any, cols: number, rows: number, text: string, x: number, y: number,
    scale: number, value: number) {
  for (let g = 0; g < text.length; g++) {
    drawGlyph(cells, cols, rows, GLYPHS[text[g]] ?? 0, x + g * 4 * scale, y, scale, value)
  }
}

sources.footer.ts:
// The footer: Previous and Next, the name of what shows, the frame rate and
// Hide, along the bottom. It is drawn in the picture's own cells, not as
// JSX: frameos.pixels cannot sit inside a JSX tree, and a second node drawing
// over it makes the render more than one node, after which the panel gets
// every cell again each frame (docs/realtime-rendering.md). The strip is
// drawn again only when its text changes (the frame rate, once a second);
// each frame it is copied over the bottom rows and what the picture had there
// is put back before the next step, so the footer neither slows what it
// measures nor feeds it, and the panel writes its cells only when they change.
import { drawGlyph, drawText, textWidth } from './font'

/** What a tap at a cell is: a button, the bar between them, the bottom edge
 *  that brings a hidden footer back, or nothing of the footer's. */
export type FooterHit = 'prev' | 'next' | 'hide' | 'show' | 'bar' | ''

const PREV = 0x1511 // the font's < and >
const NEXT = 0x4454
const ROWS = 9 // dots: a margin, a button (its glyph and a dot round it), a margin
const NARROWEST = 32 // dots: the two arrows and Hide, a dot round each glyph

let fps: number | null = null
let frames = 0
let windowStart = 0

/** One more render: the rate over the last second, or null for a while. */
export function countFrame(): number | null {
  const now = Date.now()
  if (!windowStart) windowStart = now
  frames++
  const elapsed = now - windowStart
  if (elapsed >= 1000) {
    fps = Math.round((frames * 1000) / elapsed)
    frames = 0
    windowStart = now
  }
  return fps
}

/** Count from the next render: another effect, or the footer shown again.
 *  The number shown stays until the new one is in, unless `forget`. */
export function restartCount(forget = false) {
  frames = 0
  windowStart = 0
  if (forget) fps = null
}

// Where it goes, in cells: `scale` cells a dot of the font, `height` rows from
// `top` to the bottom (0: no room), the dot grid `left` cells in; and the
// cells, cell and image size that was worked out for.
let cols = 0
let rows = 0
let scale = 1
let height = 0
let top = 0
let left = 0
// How many dots wide the buttons' row is: the grid's width, or on a round
// panel the circle's where the strip lies.
let span = 0
let placedKind: any = null
let placedSize = 0
let placedWidth = 0
let placedHeight = 0
let placedRound = false
// The buttons' dots, [from, to), from the last strip drawn.
let prevFrom = 0
let prevTo = 0
let nextFrom = 0
let nextTo = 0
let hideFrom = 0
let strip: any = null
// What the strip shows, compared every frame without making a string.
let drawnName = ''
let drawnRate: number | null = null
let drawnBar = -1
let drawnInk = -1
let drawnLive = true

/** The grid of `cells` this frame: `cols` x `rows`, `size` pixels a cell, a
 *  `width` x `height` image. The font's dot is ~4 px, more on a large
 *  screen, and never under a cell. `round`: only the circle inside the
 *  image shows, so the strip goes up into it and its buttons within the
 *  circle's width there, 12 px in from the rim. */
export function placeFooter(cells: any, gridCols: number, gridRows: number, size: number, width: number,
    imageHeight: number, round = false) {
  // The same grid as last frame, as it nearly always is: nothing to work out
  // (a Math.* call is a native call on an ESP32).
  const kind = cells.constructor
  if (gridCols === cols && gridRows === rows && kind === placedKind && size === placedSize &&
      width === placedWidth && imageHeight === placedHeight && round === placedRound) return
  placedKind = kind
  placedSize = size
  placedWidth = width
  placedHeight = imageHeight
  placedRound = round
  const target = Math.max(4, Math.floor(Math.min(width, imageHeight) / 160))
  const s = Math.max(1, Math.ceil(target / size))
  cols = gridCols
  rows = gridRows
  scale = s
  // No footer on a grid too small for it: a third of its rows at most, and
  // room for the buttons.
  if (round) {
    // The strip's bottom at three quarters of the way to the rim, and its
    // buttons as wide as the circle is there.
    const r = Math.min(width, imageHeight) / 2 / size
    const inset = 12 / size
    const bottom = Math.floor(rows / 2 + r * 0.72)
    const dy = bottom - rows / 2
    const half = Math.sqrt(Math.max(0, (r - inset) * (r - inset) - dy * dy))
    span = Math.floor((2 * half) / s)
    height = ROWS * s * 3 <= rows && span >= NARROWEST ? ROWS * s : 0
    top = bottom - height
    left = Math.max(0, Math.round(cols / 2 - (span * s) / 2))
  } else {
    span = Math.floor(cols / s)
    height = ROWS * s * 3 <= rows && Math.floor(cols / s) >= NARROWEST ? ROWS * s : 0
    top = rows - height
    left = (cols % s) >> 1
  }
  // The strip and what it covers are arrays of the cells' own kind: QuickJS
  // copies one typed array into another with memmove only when the two are
  // the same kind, and a byte at a time through property access otherwise.
  strip = height ? new kind(cols * height) : null
  under = null
  drawnBar = -1
}

function box(cells: any, x0: number, x1: number, value: number) {
  for (let y = scale; y < (ROWS - 1) * scale; y++) cells.fill(value, y * cols + left + x0 * scale, y * cols + left + x1 * scale)
}

/** The strip for this name and rate, in the picture's `bar` and `ink`
 *  colors; drawn again only when one of them changed. What does not fit
 *  goes, the name first, then the word FPS, then the rate. Not `live` (a
 *  panel where every change costs a refresh, so nothing animates): no rate
 *  and no Hide, only the arrows and the name. */
export function drawFooter(name: string, bar: number, ink: number, live = true) {
  if (!strip || (fps === drawnRate && bar === drawnBar && ink === drawnInk && name === drawnName && live === drawnLive)) return
  drawnName = name
  drawnRate = fps
  drawnBar = bar
  drawnInk = ink
  drawnLive = live
  const rate = fps === null ? '--' : String(fps)
  strip.fill(bar)
  const dots = span
  const hideText = 'HIDE'
  for (const [pad, named, label] of [[3, true, ' FPS'], [2, true, ' FPS'], [1, true, ' FPS'], [2, false, ' FPS'],
      [1, false, ' FPS'], [1, false, ''], [1, false, null]] as [number, boolean, string | null][]) {
    const button = 3 + 2 * pad
    const hideWidth = live ? textWidth(hideText, 1) + 2 * pad : 0
    const text = label === null || !live ? '' : rate + label
    const textWide = text ? textWidth(text, 1) + 2 : 0
    const nameWide = named ? textWidth(name, 1) + 2 : 0
    if (1 + button + 1 + button + nameWide + textWide + 2 + hideWidth + 1 > dots) continue
    prevFrom = 1
    prevTo = prevFrom + button
    nextFrom = prevTo + 1
    nextTo = nextFrom + button
    // Without Hide, no tap is one.
    hideFrom = live ? dots - 1 - hideWidth : dots + 2
    box(strip, prevFrom, prevTo, ink)
    box(strip, nextFrom, nextTo, ink)
    if (live) box(strip, hideFrom, dots - 1, ink)
    const y = 2 * scale
    drawGlyph(strip, cols, height, PREV, left + (prevFrom + pad) * scale, y, scale, bar)
    drawGlyph(strip, cols, height, NEXT, left + (nextFrom + pad) * scale, y, scale, bar)
    if (live) drawText(strip, cols, height, hideText, left + (hideFrom + pad) * scale, y, scale, bar)
    if (named) drawText(strip, cols, height, name, left + (nextTo + 2) * scale, y, scale, ink)
    if (text) drawText(strip, cols, height, text, left + (hideFrom - textWide) * scale, y, scale, ink)
    return
  }
}

// What the footer covers now, put back before the picture's next step. The
// view of those rows is kept, not made again each frame.
let under: any = null
let held: any = null
let heldAt = 0
let view: any = null
let viewOf: any = null
let viewAt = -1

/** The strip over the bottom rows of `cells` (a grid `cols` wide). */
export function footerIn(cells: any) {
  if (!strip) return
  const at = top * cols
  const count = strip.length
  if (cells !== viewOf || at !== viewAt || view.length !== count) {
    view = cells.subarray(at, at + count)
    viewOf = cells
    viewAt = at
  }
  if (!under || under.length !== count) under = new placedKind(count)
  under.set(view)
  cells.set(strip, at)
  held = cells
  heldAt = at
}

/** What the picture had under the footer, back where it was. */
export function footerOut() {
  if (!held || !under) return
  held.set(under, heldAt)
  held = null
}

/** A tap at cell (x, y): which part of the footer it is on. */
export function footerHit(x: number, y: number, shown: boolean): FooterHit {
  if (!height || y < top || (placedRound && y >= top + height) || x < 0) return ''
  if (!shown) return 'show'
  if (!prevTo) return 'bar'
  // Each button takes the taps of half the gap beside it, and the edges.
  const dot = (x - left) / scale
  if (dot < prevTo + 0.5) return 'prev'
  if (dot < nextTo + 1) return 'next'
  if (dot >= hideFrom - 1) return 'hide'
  return 'bar'
}
